"""Keep the running conversation under the model context limit."""

MAX_TOKENS = 180_000
KEEP_TAIL = 5

# The standing rules the compacted context MUST still contain. Checked, not hoped for.
REQUIRED_INSTRUCTIONS = (
    "never push to main",
    "run the suite before you commit",
)


class CompactionLostInstructions(RuntimeError):
    """Raised when a summary dropped a rule the operator imposed."""


def _summarise(messages):
    text = "\n".join(m["content"] for m in messages)
    reply = client.messages.create(
        model="a-model",
        messages=[{"role": "user", "content": "Condense this transcript:\n" + text}],
    )
    return {"role": "user", "content": reply.content[0].text}


def summarise_history(messages):
    return _summarise(messages)


def assert_invariants_preserved(messages):
    blob = "\n".join(m["content"] for m in messages)
    missing = [rule for rule in REQUIRED_INSTRUCTIONS if rule not in blob]
    if missing:
        raise CompactionLostInstructions(missing)


def compact_context(messages, token_count, rules_message):
    if token_count < MAX_TOKENS:
        return messages
    summary = _summarise(messages[:-KEEP_TAIL])
    compacted = [rules_message, summary] + messages[-KEEP_TAIL:]
    assert_invariants_preserved(compacted)
    return compacted
